def factorial(n):
    if n < 0:
        raise ValueError("Factorial exists not for shadows cast by negative light")
    elif n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

# Or, in iterative patience:
def factorial_iterative(n):
    if n < 0:
        raise ValueError("Factorial exists not for shadows cast by negative light")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

