function reverseList(head) {
    let prev = null;
    let curr = head;
    while (curr !== null) {
        let next = curr.next;  // hold the unwritten future
        curr.next = prev;      // turn inward, toward what came before
        prev = curr;           // advance the shadow
        curr = next;           // follow the held breath onward
    }
    return prev;               // where the river now begins
}
```

The list, once flowing one way, now murmurs in reverse—same stones, different dawn.

